/** `entity/RoostGoal.java`: the runtime's `RoostGoal`. */
export function roostGoalJava(entityPackage: string): string {
  return `// Generated by MCSuperMods: msm_runtime's RoostGoal (goals) as a plain class.
package ${entityPackage};

import java.util.EnumSet;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.Vec3;
import ${entityPackage}.HabitGoal.Roost;

/**
 * {@code roost} (ADR 0109 D3 as amended after B524, bat-like): by day ({@code daylight}) or now and then while it has
 * nothing to do ({@code when_idle}: one chance in {@link #IDLE_CHANCE} at each goal check, and at the latest at the
 * {@link #IDLE_MAX_CHECKS}th, so an idle mob under a ceiling always roosts within about 160 ticks), a mob with a block
 * above it within {@code range} (one whose underside is sturdy) goes up under it and hangs there upside down
 * ({@link MobHabits#setRoosting}: no gravity, no motion, the box's top at the block's underside). It lets go when it is hurt, gets a target, the block goes, a player who is not a spectator
 * comes within {@link #WAKE_RANGE} blocks, or (roosting by day only) the day ends, and then waits
 * {@link MobHabits#ROOST_COOLDOWN} ticks before roosting again. A mob that cannot fly hangs only
 * from a block right over its head. The way up gives up after {@link #GIVE_UP_TICKS}.
 */
public class RoostGoal extends Goal {
    /** A player this near wakes the mob, and keeps it from roosting. */
    public static final double WAKE_RANGE = 4.0;
    public static final int GIVE_UP_TICKS = 100;
    /** One chance in this many, at each goal check (every other tick), for {@code when_idle}. */
    static final int IDLE_CHANCE = 40;
    /** The goal check at which an idle roost starts whatever the chance said (B544: the wait has an upper bound). */
    public static final int IDLE_MAX_CHECKS = 2 * IDLE_CHANCE;

    private final PathfinderMob mob;
    private final MobHabits habits;
    private final Roost roost;
    private final boolean flies;
    /** The block it hangs from. */
    private BlockPos ceiling;
    private int ticks;
    /** Whether it hung during this run of the goal (letting go then ends the goal). */
    private boolean hung;
    /** The idle goal checks since the last try, for {@link #IDLE_MAX_CHECKS}. */
    private int idleChecks;

    public RoostGoal(PathfinderMob mob, MobHabits habits, Roost roost, boolean flies) {
        this.mob = mob;
        this.habits = habits;
        this.roost = roost;
        this.flies = flies;
        setFlags(EnumSet.of(Flag.MOVE, Flag.LOOK, Flag.JUMP));
    }

    /** The first block above the mob within {@code range} whose underside is sturdy, or null. */
    public static BlockPos ceilingAbove(PathfinderMob mob, int range) {
        Level level = mob.level();
        BlockPos head = BlockPos.containing(mob.getX(), mob.getBoundingBox().maxY - 1.0e-3, mob.getZ());
        for (int dy = 1; dy <= range; dy++) {
            BlockPos p = head.above(dy);
            if (level.getBlockState(p).isAir()) {
                continue;
            }
            return level.getBlockState(p).isFaceSturdy(level, p, Direction.DOWN) ? p : null;
        }
        return null;
    }

    private boolean playerNear() {
        return mob.level().getNearestPlayer(mob.getX(), mob.getY(), mob.getZ(), WAKE_RANGE, p -> !p.isSpectator()) != null;
    }

    private boolean wanted() {
        if (mob.getTarget() != null || mob.isPassenger() || mob.isLeashed() || playerNear()) {
            return false;
        }
        return roost.daylight() && mob.level().isBrightOutside() || roost.whenIdle();
    }

    @Override
    public boolean canUse() {
        if (habits.roosting()) {
            ceiling = ceilingAbove(mob, roost.range());
            return true; // loaded hanging, or hung by a command: carry on
        }
        if (habits.roostCooldown() > 0 || !wanted()) {
            return false;
        }
        if (!(roost.daylight() && mob.level().isBrightOutside()) && mob.getRandom().nextInt(IDLE_CHANCE) != 0
                && ++idleChecks < IDLE_MAX_CHECKS) {
            return false;
        }
        idleChecks = 0;
        ceiling = ceilingAbove(mob, flies ? roost.range() : 1);
        return ceiling != null;
    }

    @Override
    public boolean canContinueToUse() {
        if (ceiling == null || mob.level().getBlockState(ceiling).isAir()) {
            return false;
        }
        if (!habits.roosting()) {
            return !hung && ticks < GIVE_UP_TICKS && wanted();
        }
        return wanted();
    }

    @Override
    public boolean requiresUpdateEveryTick() {
        return true;
    }

    @Override
    public void start() {
        ticks = 0;
        hung = habits.roosting();
        mob.getNavigation().stop();
    }

    @Override
    public void stop() {
        if (habits.roosting()) {
            habits.setRoosting(false, mob.position());
        }
        ceiling = null;
    }

    /** Where the mob's feet go to hang from {@link #ceiling}: under its middle, the box's top at its underside. */
    private Vec3 hangAt() {
        return new Vec3(ceiling.getX() + 0.5, ceiling.getY() - mob.getBbHeight(), ceiling.getZ() + 0.5);
    }

    @Override
    public void tick() {
        if (ceiling == null) {
            return;
        }
        Vec3 at = hangAt();
        if (habits.roosting()) {
            mob.setPos(at.x, at.y, at.z);
            mob.setDeltaMovement(Vec3.ZERO);
            return;
        }
        ticks++;
        if (!flies || mob.position().distanceToSqr(at) < 0.25) {
            habits.setRoosting(true, at);
            hung = true;
            return;
        }
        mob.getMoveControl().setWantedPosition(at.x, at.y, at.z, 1.0);
    }
}
`;
}

/** `entity/CollectItemsGoal.java`: the runtime's `CollectItemsGoal`. */
export function collectItemsGoalJava(entityPackage: string): string {
  return `// Generated by MCSuperMods: msm_runtime's CollectItemsGoal (goals) as a plain class.
package ${entityPackage};

import java.util.EnumSet;
import java.util.List;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.phys.Vec3;
import ${entityPackage}.HabitGoal.CollectItems;

/**
 * {@code collect_items} (ADR 0109 D4 as amended after B524, allay-like): once a player has given the mob an item
 * ({@link MobHabits#liked}), it fetches items of that kind lying free within {@code range} blocks (looking about every
 * {@link #SEARCH_INTERVAL} ticks; never an item it threw itself, which carries it as the thrower) and carries up to a
 * stack. When its load is full or nothing is left to fetch, it brings the load to the note block it heard within the
 * last 30 seconds ({@code note_blocks}), else to its owner, and throws it there from {@link #DROP_RANGE} blocks (to the
 * owner only that player can pick it up). The way to an item gives up after {@link #GIVE_UP_TICKS}.
 */
public class CollectItemsGoal extends Goal {
    static final int SEARCH_INTERVAL = 10;
    public static final double REACH = 1.5;
    public static final double DROP_RANGE = 2.5;
    public static final int GIVE_UP_TICKS = 200;
    /** Ticks before the owner can pick a thrown load up. */
    static final int PICKUP_DELAY = 10;

    private final PathfinderMob mob;
    /** Calls of canUse left before the next look round (the selector does not ask every tick). */
    private int searchIn;
    private final MobHabits habits;
    private final CollectItems collect;
    private ItemEntity aim;
    private int ticks;

    public CollectItemsGoal(PathfinderMob mob, MobHabits habits, CollectItems collect) {
        this.mob = mob;
        this.habits = habits;
        this.collect = collect;
        setFlags(EnumSet.of(Flag.MOVE));
    }

    private ItemEntity nearest() {
        double range = collect.range();
        List<ItemEntity> near = mob.level().getEntitiesOfClass(ItemEntity.class, mob.getBoundingBox().inflate(range), habits::wants);
        ItemEntity best = null;
        for (ItemEntity item : near) {
            if (mob.distanceToSqr(item) <= range * range && (best == null || mob.distanceToSqr(item) < mob.distanceToSqr(best))) {
                best = item;
            }
        }
        return best;
    }

    private boolean full() {
        ItemStack carried = habits.carried();
        return !carried.isEmpty() && carried.getCount() >= carried.getMaxStackSize();
    }

    /** Where the load goes now: the heard note block's top, the owner, or null. */
    private Vec3 destination() {
        BlockPos note = habits.noteBlock();
        if (note != null) {
            return Vec3.atBottomCenterOf(note.above());
        }
        Player owner = habits.owner();
        return owner != null && owner.isAlive() && !owner.isSpectator() ? owner.position() : null;
    }

    @Override
    public boolean canUse() {
        if (habits.liked().isEmpty() || habits.playingDead() || --searchIn > 0) {
            return false;
        }
        searchIn = SEARCH_INTERVAL / 2;
        aim = full() ? null : nearest();
        return aim != null || !habits.carried().isEmpty() && destination() != null;
    }

    @Override
    public boolean canContinueToUse() {
        if (habits.liked().isEmpty() || ticks >= GIVE_UP_TICKS) {
            return false;
        }
        return aim != null ? habits.wants(aim) : !habits.carried().isEmpty() && destination() != null;
    }

    @Override
    public boolean requiresUpdateEveryTick() {
        return true;
    }

    @Override
    public void start() {
        ticks = 0;
    }

    @Override
    public void stop() {
        aim = null;
        mob.getNavigation().stop();
    }

    @Override
    public void tick() {
        ticks++;
        if (!(mob.level() instanceof ServerLevel level)) {
            return;
        }
        if (aim != null) {
            if (mob.distanceTo(aim) <= REACH) {
                take(aim);
                aim = full() ? null : nearest();
                ticks = 0;
            } else if (mob.getNavigation().isDone() || mob.tickCount % 10 == 0) {
                mob.getNavigation().moveTo(aim, collect.speed());
            }
            return;
        }
        Vec3 to = destination();
        if (to == null) {
            return;
        }
        if (mob.position().distanceTo(to) <= DROP_RANGE) {
            deliver(level, to);
            return;
        }
        if (mob.getNavigation().isDone() || mob.tickCount % 10 == 0) {
            mob.getNavigation().moveTo(to.x, to.y, to.z, collect.speed());
        }
    }

    private void take(ItemEntity item) {
        ItemStack stack = item.getItem();
        ItemStack carried = habits.carried();
        int room = carried.isEmpty() ? stack.getMaxStackSize() : carried.getMaxStackSize() - carried.getCount();
        int amount = Math.min(room, stack.getCount());
        if (amount <= 0) {
            return;
        }
        mob.take(item, amount);
        if (carried.isEmpty()) {
            habits.setCarried(stack.copyWithCount(amount));
        } else {
            carried.grow(amount);
        }
        stack.shrink(amount);
        if (stack.isEmpty()) {
            item.discard();
        }
    }

    private void deliver(ServerLevel level, Vec3 to) {
        ItemStack load = habits.carried();
        habits.setCarried(ItemStack.EMPTY);
        ItemEntity thrown = new ItemEntity(level, mob.getX(), mob.getEyeY() - 0.3, mob.getZ(), load);
        Vec3 push = to.subtract(mob.position());
        thrown.setDeltaMovement(push.lengthSqr() < 1.0e-6 ? Vec3.ZERO : push.normalize().scale(0.2).add(0, 0.1, 0));
        thrown.setPickUpDelay(PICKUP_DELAY);
        thrown.setThrower(mob);
        Player owner = habits.owner();
        if (habits.noteBlock() == null && owner != null) {
            thrown.setTarget(owner.getUUID());
        }
        level.addFreshEntity(thrown);
        mob.getNavigation().stop();
    }
}
`;
}

/** `entity/DigForItemsGoal.java`: the runtime's `DigForItemsGoal`. */
export function digForItemsGoalJava(entityPackage: string): string {
  return `// Generated by MCSuperMods: msm_runtime's DigForItemsGoal (goals) as a plain class.
package ${entityPackage};

import java.util.EnumSet;
import net.minecraft.core.BlockPos;
import net.minecraft.core.particles.BlockParticleOption;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.level.block.state.BlockState;
import ${entityPackage}.HabitGoal.DigItems;

/**
 * {@code dig_items} (ADR 0109 D4, sniffer-like): once its cooldown is over, the mob walks to the nearest of its
 * {@code dig_blocks} within {@link #SEARCH} blocks (looking about every {@link #SEARCH_INTERVAL} ticks), digs there for
 * {@link MobHabits#DIG_TICKS} ticks (the block's particles) and drops a roll of {@code loot_table}
 * ({@link MobHabits#digUp}), then waits {@code interval_ticks}. A walk gives up after {@link #GIVE_UP_TICKS}.
 */
public class DigForItemsGoal extends Goal {
    public static final int SEARCH = 8;
    static final int SEARCH_INTERVAL = 20;
    public static final int GIVE_UP_TICKS = 400;

    private final PathfinderMob mob;
    private final MobHabits habits;
    private final DigItems dig;
    private BlockPos site;
    private int searchIn;
    private int ticks;
    private int digging;

    public DigForItemsGoal(PathfinderMob mob, MobHabits habits, DigItems dig) {
        this.mob = mob;
        this.habits = habits;
        this.dig = dig;
        setFlags(EnumSet.of(Flag.MOVE, Flag.JUMP));
    }

    private boolean diggable(BlockPos p) {
        return habits.isDigBlock(mob.level().getBlockState(p)) && mob.level().getBlockState(p.above()).getCollisionShape(mob.level(), p.above()).isEmpty();
    }

    private BlockPos search() {
        BlockPos below = mob.getBlockPosBelowThatAffectsMyMovement();
        if (mob.onGround() && habits.isDigBlock(mob.level().getBlockState(below))) {
            return below;
        }
        if (--searchIn > 0) {
            return null;
        }
        searchIn = SEARCH_INTERVAL / 2; // the selector asks about every other tick
        BlockPos at = mob.blockPosition();
        BlockPos best = null;
        for (BlockPos p : BlockPos.betweenClosed(at.offset(-SEARCH, -3, -SEARCH), at.offset(SEARCH, 2, SEARCH))) {
            if (diggable(p) && (best == null || p.distSqr(at) < best.distSqr(at))) {
                best = p.immutable();
            }
        }
        return best;
    }

    @Override
    public boolean canUse() {
        if (habits.digCooldown() > 0 || habits.playingDead() || mob.isPassenger()) {
            return false;
        }
        site = search();
        return site != null;
    }

    @Override
    public boolean canContinueToUse() {
        return site != null && habits.digCooldown() == 0 && ticks < GIVE_UP_TICKS && habits.isDigBlock(mob.level().getBlockState(site));
    }

    @Override
    public boolean requiresUpdateEveryTick() {
        return true;
    }

    @Override
    public void start() {
        ticks = 0;
        digging = 0;
        mob.getNavigation().moveTo(site.getX() + 0.5, site.getY() + 1, site.getZ() + 0.5, dig.speed());
    }

    @Override
    public void stop() {
        site = null;
        digging = 0;
        mob.getNavigation().stop();
    }

    /** Ticks spent digging on the current site (for the GameTests). */
    public int digging() {
        return digging;
    }

    @Override
    public void tick() {
        ticks++;
        BlockPos below = mob.getBlockPosBelowThatAffectsMyMovement();
        if (!mob.onGround() || !below.equals(site)) {
            digging = 0;
            if (mob.getNavigation().isDone()) {
                mob.getNavigation().moveTo(site.getX() + 0.5, site.getY() + 1, site.getZ() + 0.5, dig.speed());
            }
            return;
        }
        mob.getNavigation().stop();
        digging++;
        if (mob.level() instanceof ServerLevel level) {
            BlockState state = level.getBlockState(site);
            if (digging % 5 == 0) {
                level.sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, state), mob.getX(), site.getY() + 1.0, mob.getZ(), 4,
                        0.3, 0.05, 0.3, 0.0);
            }
            if (digging >= MobHabits.DIG_TICKS) {
                habits.digUp(level);
                site = null;
            }
        }
    }
}
`;
}

